<script setup lang="ts">
interface PortfolioListItem { id: number; slug: string; title: string; description?: string | null; type: 'project' | 'visual' | 'tool'; cover?: { url: string; alt?: string; kind?: string } | null; featured: boolean; publishedAt: string; updatedAt: string; labels: string[]; capabilities: string[]; mediaSummary: { imageCount: number; videoCount: number; promptCount: number } }
interface PortfolioResponse { items: PortfolioListItem[]; pagination: { page: number; pageSize: number; total: number; totalPages: number }; filters: { types: Array<{ value: string; count: number }>; media: Array<{ value: string; count: number }>; years: number[]; tags: Array<{ value: string; count: number }> } }

const route = useRoute()
const router = useRouter()
const search = ref(typeof route.query.q === 'string' ? route.query.q : '')
const type = ref(typeof route.query.type === 'string' ? route.query.type : '')
const media = ref(typeof route.query.media === 'string' ? route.query.media : '')
const year = ref(typeof route.query.year === 'string' ? route.query.year : '')
const sort = ref(typeof route.query.sort === 'string' ? route.query.sort : 'featured')
const page = ref(Number(route.query.page) || 1)
const query = computed(() => ({ ...(search.value ? { q: search.value } : {}), ...(type.value ? { type: type.value } : {}), ...(media.value ? { media: media.value } : {}), ...(year.value ? { year: year.value } : {}), ...(sort.value !== 'featured' ? { sort: sort.value } : {}), ...(page.value > 1 ? { page: page.value } : {}) }))
const { data, pending, error } = await useFetch<{ success: boolean; data: PortfolioResponse }>('/api/portfolio', { query, watch: [query] })
const payload = computed(() => data.value?.data)
const items = computed(() => payload.value?.items || [])
const active = computed(() => Boolean(search.value || type.value || media.value || year.value || sort.value !== 'featured'))
const typeLabels: Record<string, string> = { project: '项目 · 实验', visual: '视觉 · 影像', tool: '工具 · 仓库' }
const typeShort: Record<string, string> = { project: 'PROJECT', visual: 'VISUAL LOG', tool: 'PROMPT VAULT' }
const capabilityLabels: Record<string, string> = { code: '代码', 'interactive-demo': '在线演示', video: '视频', gallery: '影像', search: '可搜索', copy: '可复制', download: '可下载' }
const mediaLabels: Record<string, string> = { image: '图片', video: '视频', gif: 'GIF', code: '代码', embed: '演示', download: '下载' }
function syncRoute() { const next: Record<string, string> = {}; for (const [key, value] of Object.entries(query.value)) if (value !== undefined && value !== '') next[key] = String(value); router.replace({ query: next }) }
watch([search, type, media, year, sort], () => { page.value = 1; syncRoute() })
watch(page, syncRoute)
function clearFilters() { search.value = ''; type.value = ''; media.value = ''; year.value = ''; sort.value = 'featured'; page.value = 1 }
function formatDate(value: string) { return value ? new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(value)) : '' }
function cardMeta(item: PortfolioListItem) { if (item.type === 'tool') return item.mediaSummary.promptCount ? `${item.mediaSummary.promptCount} 条提示词` : '可检索工具'; if (item.type === 'visual') return item.mediaSummary.videoCount ? `${item.mediaSummary.videoCount} 段影像` : `${item.mediaSummary.imageCount} 张影像`; return item.capabilities.includes('interactive-demo') ? '在线演示' : '项目档案' }
useHead({ title: '作品 · FAN / Y ARCHIVE' })
</script>

<template>
  <main class="portfolio-page">
    <section class="portfolio-hero"><div class="hero-copy"><span class="eyebrow">PORTFOLIO ARCHIVE</span><h1>作品</h1><p>记录我的项目、影像与工具，探索创作过程中留下的过程与结果。</p><strong>{{ payload?.pagination.total || 0 }} <span>项已发布</span></strong></div><div class="coordinate-mark" aria-label="站点环境标记"><span class="orbital-ring" /><span class="orbital-dot" /><small>31.2304°N<br>121.4737°E</small></div></section>
    <section class="filter-bar" aria-label="作品筛选"><label class="search-field"><span aria-hidden="true">⌕</span><input v-model="search" type="search" placeholder="搜索作品标题、描述或标签" aria-label="搜索作品" /></label><div class="segmented" role="group" aria-label="作品类型"><button :class="{ active: !type }" type="button" @click="type = ''">全部</button><button v-for="option in payload?.filters.types || []" :key="option.value" :class="{ active: type === option.value }" type="button" @click="type = option.value">{{ typeLabels[option.value] || option.value }}</button></div><select v-model="media" aria-label="按媒介筛选"><option value="">全部媒介</option><option v-for="option in payload?.filters.media || []" :key="option.value" :value="option.value">{{ mediaLabels[option.value] || option.value }} ({{ option.count }})</option></select><select v-model="year" aria-label="按年份筛选"><option value="">全部年份</option><option v-for="option in payload?.filters.years || []" :key="option" :value="String(option)">{{ option }}</option></select><select v-model="sort" aria-label="作品排序"><option value="featured">精选优先</option><option value="published">最新发布</option><option value="updated">最近更新</option></select><span class="result-count">共 {{ payload?.pagination.total || 0 }} 项</span><button v-if="active" class="clear-button" type="button" @click="clearFilters">清除</button></section>
    <section class="portfolio-content" aria-live="polite"><div v-if="pending" class="loading-grid"><div v-for="n in 6" :key="n" class="skeleton-card"><div /><span /><span /><i /></div></div><el-alert v-else-if="error" type="error" title="作品暂时无法加载" description="请稍后重试，或返回首页继续浏览。" show-icon :closable="false" /><div v-else-if="!items.length" class="empty-state"><span>◇</span><h2>还没有匹配的作品</h2><p>尝试清除筛选，或换一个关键词。</p><button type="button" @click="clearFilters">清除筛选</button></div><div v-else class="portfolio-grid"><NuxtLink v-for="item in items" :key="item.id" :to="`/portfolio/${item.slug}`" class="portfolio-card"><div class="card-media"><img v-if="item.cover?.url" :src="item.cover.url" :alt="item.cover.alt || item.title" loading="lazy" /><div v-else class="media-fallback"><span>{{ typeShort[item.type] }}</span><b>{{ item.title.slice(0, 1) }}</b></div><span class="type-badge"><span aria-hidden="true">{{ item.type === 'visual' ? '▧' : item.type === 'tool' ? '◇' : '□' }}</span>{{ typeShort[item.type] }}</span><span v-if="item.type === 'visual' && item.capabilities.includes('video')" class="play-mark" aria-label="包含视频">▶</span></div><div class="card-body"><div class="card-heading"><h2>{{ item.title }}</h2><span v-if="item.featured" class="featured">精选</span></div><p>{{ item.description || '打开查看完整作品记录。' }}</p><div class="capabilities"><span v-for="capability in item.capabilities.slice(0, 2)" :key="capability">{{ capabilityLabels[capability] || capability }}</span><span v-if="!item.capabilities.length">{{ cardMeta(item) }}</span></div><footer><div class="tags"><span v-for="tag in item.labels.slice(0, 3)" :key="tag">{{ tag }}</span></div><time :datetime="item.updatedAt">{{ formatDate(item.updatedAt) }}</time></footer></div></NuxtLink></div><div v-if="payload?.pagination.totalPages > 1" class="pager"><button :disabled="page <= 1" type="button" aria-label="上一页" @click="page--">←</button><span>{{ page }} / {{ payload?.pagination.totalPages }}</span><button :disabled="page >= (payload?.pagination.totalPages || 1)" type="button" aria-label="下一页" @click="page++">→</button></div></section>
  </main>
</template>

