,247,255,.06);backdrop-filter:blur(18px)}.search-field{display:flex;align-items:center;gap:8px;flex:1;min-width:180px;padding:0 11px;border:1px solid rgba(137,186,211,.25);border-radius:8px;color:#8da8b7;background:rgba(2,12,23,.45)}.search-field span{font-size:22px;line-height:1}.search-field input{width:100%;min-height:38px;border:0;outline:0;color:#dceff4;background:transparent;font-size:12px}.search-field input::placeholder{color:#75909f}.segmented{display:flex;overflow:auto;border:1px solid rgba(137,186,211,.2);border-radius:8px}.segmented button,.clear-button{min-height:38px;padding:0 15px;border:0;border-right:1px solid rgba(137,186,211,.15);color:#9eb5c1;background:transparent;font-size:12px;white-space:nowrap;cursor:pointer}.segmented button:last-child{border-right:0}.segmented button:hover,.segmented button.active{color:#6cdef6;background:rgba(31,161,200,.14)}.filter-bar select{min-height:38px;border:1px solid rgba(137,186,211,.23);border-radius:8px;padding:0 10px;color:#b6cad4;background:#0a1b2c;font-size:12px}.result-count{margin-left:auto;color:#8ea7b5;font:11px var(--font-mono);white-space:nowrap}.clear-button{border:1px solid rgba(92,208,237,.3);border-radius:8px;color:#7bdef5}.portfolio-content{min-height:420px}.portfolio-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.portfolio-card{overflow:hidden;border:1px solid rgba(132,181,207,.24);border-radius:13px;color:inherit;text-decoration:none;background:rgba(8,24,39,.78);box-shadow:0 12px 35px rgba(0,0,0,.18);transition:transform .24s ease,border-color .24s ease,box-shadow .24s ease}.portfolio-card:hover,.portfolio-card:focus-visible{transform:translateY(-4px);border-color:rgba(78,211,241,.76);box-shadow:0 18px 45px rgba(0,0,0,.3),0 0 0 1px rgba(78,211,241,.18)}.card-media{position:relative;aspect-ratio:16/9;overflow:hidden;border-bottom:1px solid rgba(132,181,207,.2);background:#071726}.card-media img{width:100%;height:100%;object-fit:cover;display:block;filter:saturate(.82) 